) AS (
  VALUES 
    (712::BIGINT, 'Es una excelente persona pero se nota que la electrónica de potencia no es su fuerte, ya que el mismo no sabe cómo recomendar algunas soluciones viables ni explicar fenómenos que ocurren durante los proyectos del laboratorio. Eso sí, está muy dispuesto a la ayuda y califica sumamente bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '20d5184e16af0784e24b6d20c6b28a31ab74b23dd264377bb0f22b59a94d0b5b'::TEXT, ARRAY[3060]::BIGINT[]),
    (712::BIGINT, 'Es excelente explicando la materia, a mi gusto tarda demasiado en hacerlo pero todo queda sumamente claro. Tiene que hacer ejercicios adicionales a los vistos en clase, ya que los mismos son muy básicos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '124b5e80c21a704ca9b6bd13b00094a9b941422a1245bfbe849e7c4f16e53a0e'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'El curso no tiene tantos temas y son bastante fáciles si le pone siquiera un poco. El profe explica todo paso a paso, lo que a veces aburre bastante pero es de mucha ayuda; tiene una linda personalidad y es una excelente persona. Haga ejercicios por su cuenta, los exámenes no se parecen a lo visto'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'fda71ae5f1d2282df999b226cd35b30fa1daf6e56b351e4fe01057b9d48e7338'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Califica justo, el profe es exelente calificando, coincido que es un de los mejores de meca, super recomendado, solo haga todos los ejercicios de la tarea y presentacion y pasa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9d4c840bb9757f988c656a50059ebf301ff3ecee15ef35e07c59e30de7ff8f15'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Coincido en que es de los mejores profes de Meca. Explica muy bien y todos los temas vistos en clase quedan super claros. Le molesta que la gente llegue tarde. Importante hacer los ejercicios recomendados de la tarea. A veces puede andar de mal humor, pero en general es super buena gente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '37be38ec1b0ecdcd9dc1c9752d55d40ffc0190d1810fc799362759b1d047dd50'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'De los mejores profesores de Meca. Si nota que uno se esfuerza lo ayuda mucho. Las clases son entretenidas y hacer las tareas son útiles para los exámenes. Es super simpático y buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '963dcbefd8dbf8cc7de2eb6e120fe0136c321c3b6326d3f41cf58aa592f1f5ba'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Es un profesor increíble, de los mejores de Meca y del tec en general. Recomiendo muchísimo ir a consulta, el profe es muy claro y ayuda demasiado, le cambia a uno la forma de ver y analizar las cosas. Es necesario hacer todas las tareas bien y a consciencia, sino no se puede esperar pasar el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'bcb3a41666eb4795746f05d1c90095b52b889a840fa2cc7ecc5dee27272b2ae4'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'EL MEJOR PROFE DE MECA TQM JUANCA'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '7ddc5ef9504e1418b38588fafbe992419a5b44f547f3590ad8b7d33313a1bd03'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'El profe no maneja tan bien la teoría. Dice muchas veces que es mejor consultar con Johanna. Tiene muy buena voluntad y es empático con los estudiantes. Sólo revisa que funcionen los proyectos y todo lo demás lo revisa el asistente (evalúa ni suave ni duro).'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '87e95dbba038c5ac56e39a07c90808ee162829d4c4dab607d1aea4c3319a062b'::TEXT, ARRAY[3060]::BIGINT[]),
    (712::BIGINT, 'Un curso semipresencial en el que solo dio 3 clases presenciales. Las clases trataron de ver videos explicando la materia. El profe explica 10/10, deja ejercicios de práctica y tareas que sirven para el examen, aunque el examen suele ser más complejo y en los videos a veces faltan contenidos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6db2405e87bda7fa83be326dd6bceb3e3645860726ec71a203dbb97bc2768a6e'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'En virtual. El curso se resumio a ver videos y hacer trabajos semanales, los examenes son muy parecidos a estos trabajos, nada sorpresa. El profe es muy bueno, califica justo y es empatico. Pero el curso no es lo que esperaba, creo que se presta para mucho mas, una lastima.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2022-01-11T00:00:00+00:00'::TIMESTAMPTZ, '299068e1ca56d873bf974f5ffde3707521bbda8cf4364d064b1058e50a3c41b3'::TEXT, ARRAY[3065]::BIGINT[]),
    (712::BIGINT, 'Es un profesor excelente, ayuda mucho en consulta y es muy buena gente. Las tareas son de nivel medio y ayudan bastante para examenes. Los examenes son un poco dificiles y muy largos pero nada fuera de lo normal. El curso es sencillo pero no hay qe descuidarse. El profe es recomendable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'bb9b3506260924617d46904f8ba17d4e5233e20180a1d4798af2d4ee8d431cfd'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente profesor. Deja pocas tareas pero las que deja ayudan bastante para el examen. Muy simpático.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '29a8adc7729825c0d4c72bb3d7e91ab3939e1214b4fcc6adaa606cde2a1c5026'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Un profe muy amigable, excelente persona y siempre trata de explicar de la mejor forma. Los cursos con él son muy didácticos y simple busca que uno aprenda. A veces puede calificar algo duro, pero seimpre trata de ser justo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '68dbcab42a1be47dc5cf28c7fb849bf061c0683599361a2862328d47bf97f22e'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4b11d5ebba655c9bfe3f777ff654773fa0d03728c1857d04efc533f4d4d295de'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Es un excelente profesor, yo lo considero de los mejores profesores en el TEC. Las clases se entienden bastante, los exámenes son justos, es muy paciente, las tareas son muy útiles, solo le faltan un poco más de consultas para los laboratorios.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'e988e6baf9d5e1fb5c5fdb32f1ed2a0dbdd7b07b3665e7ad791e800280ede87a'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'El semestre se trabajó con guías semanales en donde había que leer y ver algunos videos propios de él. Con las evaluaciones que hizo se aprende bastante de cada tema y se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'ffde25ee167597aa28f30374d0890390016c8f78ba7f2aaf9aca667fea60db4c'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Modalidad virtual. Las clases son excelentes y se ha adaptado muy bien a la virtualidad. Presenta guías de estudio y videos explicativos para cada tema. Aborda los conceptos de manera detallada. Al evaluar no es duro pero exige saber lo que se está haciendo. Las tareas preparan para el examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '2b5f1e033154f6842f27cdf10a706a7278d5a494b532255cdc977306e01727b8'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Para clases virtuales se trabajó sobre todo con guías de estudio. El primer examen estuvo un poco pasado de dificultad pero el segundo estuvo muy fácil. Es buena gente pero ocasionalmente sarcástico y lo trata de tonto a uno. Quita puntos por cosas no mencionadas en las rúbricas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '0ea9df489a97b0bb3a82b3f148c738425d1bf7f6cebe53a6b8d584d2a031c012'::TEXT, ARRAY[3065]::BIGINT[]),
    (712::BIGINT, 'El curso en si no es dificil, juanca lo hace ameno de llevar, los videos son claros y si le pide ayuda la brinda. Pero si hay que ponerle algo para pasar, las clases son asincronicas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos exámenes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '08a47c70bafa53fd5810db85786a4b5e4db7285aaad57c9cb466bc76f1c186fb'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Buen profe, se nota que le encanta lo que hace. Se adaptó bastante bien a las clases virtuales. A veces deja muchas cosas que hacer, las tareas son largas pero pocas y los exámenes son semanales.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'ebc9b3af92de038257b068acf8c053d11dd8a6f4cd485f1c072b73737276447c'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Exelente profe se acoplo muy bien a lo virtual,para los examenes hay que realizar obligatoriamente los ejercicios de la presentacion,el curso lo hace muy sencillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '8794df62790c47aba3ece02c68f90d1d3d2c3b8be9649ec1dd5637aebce33083'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Se ve que sabe lo que hace, y le pone mucho esmero a las clases. Recomendado por ser un gran profesor y una gran persona. Sí estudia bien le irá bien ya que los quices son algo duros pero manejables.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '33ed2dae6f8cebd1178f9f29bea1a887109e97419ad43ef46b28897de2d4d69e'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente profe, entre los mejores de Meca. Ayuda bastante, y enseña la materia de una forma muy clara, haciendo cada tema más interesante de lo que podría ser si solo se leyera el libro. Evalúa un toque duro, pero si estudia de fijo le va bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Respetado por los estudiantes']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'f5190207408f1f7cdfae068029320bab1dba07a35533c55d99442a0ee3006325'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'El mejor profe del TEC que he tenido hasta ahora, ama tanto la carrera que hasta da gusto ir al curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'a9e9d9cbc28133d5e724e7d97203a15aa2a6790af21e55cb05a06ec1c6d52405'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente profesor, se nota el esfuerzo que realiza para dar las clases de la mejor manera posible. Quiere lo mejor para los/las estudiantes, por lo que no dude en preguntarle algo que no comprendiera. Se aprovecha bastante el curso. 10/10'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0166a60b06e9d7700c8ee90c59d07cd1bc9580edace06ec50f14833033781b99'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Muy muy buen profe, súper apasionado por lo que hace y busca transmitirle eso al estudiante. El curso no es fácil pero él busca que uno verdaderamente aprenda y lo logre. En serio es un crack! Fácil fácil el mejor de Meca'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '6862aaf2bb1778efa19013e344bf16d7f21d24267b7baeed0f211bf61e16f88b'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ad876d7f5f615fb9e8d551e391c767c24b1005a6c4075ce3487356c039105b74'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Profe súper dedicado a los estudiantes. Es claro con la materia y califica bien. Es estricto con la puntualidad. Es amistoso y cae bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd19e21b235c595774691db874c685c3657e8062cd7b88db27ad7ab74cc9ef148'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'El Dios de Electrónica Analógica. Un ser magnífico. Explica hermoso, aunque si hay que asegurarse de entregar las tareas a tiempo, es muy estricto con eso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '78463445db2330f25d18c52c3e443a691566c0769d4195e714ed0a3debcd8ad8'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'El mejor profesor que he tenido. Se nota que le gusta dar clases. Se preocupa porque el estudiante entienda la materia y da ejemplos. Hace ejercicios de dificultad regular en clase, pero con las tareas que deja lo prepara a uno para el examen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '511157ebaa5036035166b539b55949dc05c0e3816a9390683be07e0af126503b'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente profesor. Explica muy claro. Siempre está dispuesto a ayudar si uno no entiende algo. Es muy amigable y comprensivo. De los mejores profes que he tenido.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'cbf07d144498ee4d34134ef92e4896bc86b8bed64a979a06c2c6d9f3dac3f6de'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Es un profesor excelente. Demasiado claro y bueno con los estudiantes, lo hace a uno experimentar con los instrumentos en el laboratorio. Comprende a los estudiantes y te hace pensar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'bc7c905c4cf59938996d0898359e5752d82f75cca2779db15d44d7a292f888a6'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Excelente profesor. Asegurense de practicar en este curso, de lo contrario corren el peligro de quedarse jaja. En laboratorio es excelente y apoya en lo que sea necesario y posible'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '68f78b92ce6c7f8d733300fed0f1fcf864b5e2632b22726fceba436cacc27363'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente persona y muy gracioso, la clase se hace muy llevadera. Los quizes tanto para teoría como para lab son de bueno o malo entonces hay que ponerles cuidado pero no son nada del otro mundo. Los exámenes son largos entonces casi no da tiempo de revisarlos pero tampoco nada imposible.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '0efeea676f5121585460da8b70255fe4634b0aa8d24dab78fa177eb3a715ec92'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Revisa los proyectos muy justo y trata de darte la mayor cantidad de puntos que se pueda, sí es un poco delicado con la seguridad eléctrica pero se pasa con ponerle bastante'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'e56aa0d915302ff02e501c4242cb50a44cc9a0b28a2132e53243044bb155d43a'::TEXT, ARRAY[3060]::BIGINT[]),
    (712::BIGINT, 'Muy buen profe, y el curso es fácil. Él le ayuda si ocupa algo fuera de consulta. Los proyectos con él son interesantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8245f949cb2a842a316c7aba1eec5466dfbc3e93f4a5a5a2f08c6356d1da7a90'::TEXT, ARRAY[3065]::BIGINT[]),
    (712::BIGINT, 'Se interesa mucho porque los estudiantes entiendan y que aprendan. Hace las clases entretenidas y explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8b00a6f2b96b9f8af6e9491d3673c434c362cffe5e3eb69d40783859eee8d22e'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '67bab2ab0054a182dd567fafa1b47337d8d9e0546d4d807e3e1697dc2491dd97'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Muy buena persona, ayuda al estudiante en lo que pueda'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '859e4651fe1305a0716e403bdaf458f0a089b0a81ef61223ca31ffc69ba0942b'::TEXT, ARRAY[3065]::BIGINT[]),
    (712::BIGINT, 'CRACK, es de lo mejor,, divertido, explica bien, exámenes normales y se preocupa porque uno entienda y califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '581350628f355e349c519bd044bbb0a04b051f634e2a966f99a0d90a8e015fa7'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente, ayuda en los proyectos si usted se esfuerza de antemano. En la teoría de analógica explica muy claro. A veces los problemas de diseño son un poco locos pero no imposibles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '72e04dc49ffc6b4019b7b8cbbe5e1243955f0aaa688e8d432fa6ab44c4754b09'::TEXT, ARRAY[3060, 3052]::BIGINT[]),
    (712::BIGINT, 'Excelente profe, siempre puede atender cualquier duda que se presente. Definitivamente recomendado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, '3374365a0f856fe6a1518693a7b45bd6767966cc280f32f9a2987388b9a15fe8'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Es un excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'd038fb19c5401dea1fb73068749f9bf929cf7f55310fee7c4e0625a95046720d'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Excelente persona y profesor. Se interesa en que el estudiante aprenda y si tiene dudas el las intenta resolver.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'fdea02feb427251b5622db500a3a1afced3d29373ba262f80036d420a4a62c3a'::TEXT, ARRAY[3052]::BIGINT[]),
    (712::BIGINT, 'Muy buen profe para los labs en general. Los proyectos de lab de potencia son interesantes, y se aprende mucho de esos proyectos. ACUERDESE DE SIEMPRE CUBRIR CABLE EXPUESTO. Baja muchos puntos por eso xD.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '8e27f48bd5cf5c8d5675658f6dc792ad45f954979813f776df4fa87853a8fefc'::TEXT, ARRAY[3060]::BIGINT[]),
    (712::BIGINT, 'Muy buena gente si necesitas algo te ayuda y es bastante claro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, '8474c976cb63354d293bd3aaf69d6ccd92c12c4d2182d83478161bf0826d3b16'::TEXT, ARRAY[3060]::BIGINT[]),
    (712::BIGINT, 'Califica normal y atiende cualquier duda que se tenga, por lo general ayuda bastante para que se aproveche el curso al máximo, aunque la mayoría del curso son hacer mediciones, un tanto aburrido. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'b1dbdb53a1db7ca4d23aba347e4085410dbe3c7b6a2bfddab447c349ae7b78c3'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Es muy buena gente y no califica duro. En el laboratorio deja que los estudiantes experimenten con el equipo por sí solos, pero si uno tiene dudas siempre lo atiende muy bien. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7fa45aa5b96be056220111d5f55c292f302f551212b21464bc23fbd040df2c75'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Explica lo necesario, no hay mucho que aprender, es bueno ser curioso durante el curso o hacerle preguntas para ir aprendiendo mejor como usar las cosas del lab. Durante el lab, si uno tiene dudas lo ayuda hasta uno entender. En general buen profe y muy buena gente, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, '085cf78ab7748988ae885daab8dbd6647e40fa8f48138bd83baf3e029f3c6e89'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Explica muy bien pero es estricto a la hora de calificar y los exámenes son un poco rudos pero igual se pasa y se aprende bien.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2017-09-10T00:00:00+00:00'::TIMESTAMPTZ, '08b64d48181308ca91c174257af6e00a457d5c698599dfa2b69e5cfe584b1ffe'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente profe. Sabe de lo que está hablando, pero al ser nuevo no se mide muy bien con las evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '71d3ff8391425d42d98d6652c519372c8d48febeba601bd439456608a0fed016'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Se nota que le falta experiencia como profesor, pero tampoco es malo, por lo menos para este curso si se pasa bien con él'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '87070ba7046957b9a64009a5edf382d987a8de36629fcd5b96d6eb77e13e4810'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Es buen profesor. A veces no es muy claro, pero el vuelve a explicar hasta que entiendas. Los exámenes son un poco difíciles, porque no suele pone ejercicios que sean parecidos a los resueltos en clase, tareas y quizzes'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'da03e4e1785807ca82910fc78828303b477d6535750ccc4fa67c0aab839f6246'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'El profesor es nuevo y por eso muchas veces se enreda en clases. Tarda demasiado tiempo devolviendo las evaluaciones. Nunca espere que le devuelvan una evaluación en solo 15 días, lo estipulado en el reglamento.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e991ce8b0c19b1ef96cc0bf1b995708e68b6c54aa5f14290619e56d39b377922'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'No tiene mucha experiencia por lo que a veces no logra resolver las dudas que uno posee, no es mala persona'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, '25dbcd2ed01846aec467f2ffb9d74d251cf56b58b4b6acdbbd9149cdd11f1c83'::TEXT, ARRAY[3056]::BIGINT[]),
    (712::BIGINT, 'No me pareció tan buen profe, seguro es la inexperiencia. Califica regular-duro, evaluaciones algo pasadas en dificultad y cantidad de ejercicios. A veces no explica bien. Él busca ayudar y es buena persona, pero es como si asumiera que con un ejemplo ya somos expertos. Hay que estudiar bastante.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, '2a9c9649b61c406063c5248192a17fe4e9250d603e03ad4637c51b42c9731781'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '0c9b5718a4c89eb4fa8c45c69c7349593d0a669840b10b9065ca090a62e1f89a'::TEXT, ARRAY[3056]::BIGINT[]),
    (712::BIGINT, 'Poca claridad'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6dfbff5800bec503dae66a87065246586a3a399359d1fbb6d95f6ccab6e19365'::TEXT, ARRAY[3051]::BIGINT[]),
    (712::BIGINT, 'Excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b04d692fd71e74ab3dc190b7e94c53e553ef0e9f0b9c37c673361d17bfa6fda1'::TEXT, ARRAY[3050]::BIGINT[]),
    (712::BIGINT, 'Muy buena gente y trata de ayudar al estudiante en lo que puede. Le falta experiencia como profe, pero igual es bueno. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '686213003d744e5a6737a3af47fa989d8fe80621a52b6709a15033dfb227178f'::TEXT, ARRAY[3056]::BIGINT[]),
    (712::BIGINT, 'Se ve que sabe de la materia solo que por ser nuevo no sabe como explicarla, por lo que muchas veces no aclara dudas'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2017-05-25T00:00:00+00:00'::TIMESTAMPTZ, '94fc80a89b2219e37cf7f6adc20ff08e166c4fb8d9245ba58b387968f34768f8'::TEXT, ARRAY[3056]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
